export function paintPrizeArt(target,reward){
 const category=reward.category.endsWith('_seed')?'seed':reward.category==='sp_material'?'material':reward.category;
 const asset=artwork[category+':'+(reward.recipe_id||reward.id)];if(!asset)return false;
 const node=document.createElement('span');node.className='gacha-item-art';node.style.backgroundImage='url("'+asset.url+'")';
 const f=asset.atlasFrame,v=asset.atlasViewport;
 if(f){node.style.backgroundSize=(f.columns*100)+'% '+(f.rows*100)+'%';node.style.backgroundPosition=(f.column*100/(f.columns-1))+'% '+(f.row*100/(f.rows-1))+'%';node.style.aspectRatio=(asset.pixelWidth/f.columns)+' / '+(asset.pixelHeight/f.rows);}
 else if(v){node.style.backgroundSize=(asset.pixelWidth/v.width*100)+'% '+(asset.pixelHeight/v.height*100)+'%';node.style.backgroundPosition=(v.x/(asset.pixelWidth-v.width)*100)+'% '+(v.y/(asset.pixelHeight-v.height)*100)+'%';node.style.aspectRatio=v.width+' / '+v.height;}
 target.replaceChildren(node);return true;
}
